[{"order":1,"type":"heading","text":"Build Pipelines, Asset Bundles, and Platform-Specific Optimization in Unity"},{"order":2,"type":"paragraph","text":"Mastering Unity's build system and asset management is critical for shipping performant cross-platform games. This tutorial covers programmatic builds using BuildPipeline, efficient Asset Bundle workflows, and platform-specific optimization techniques."},{"order":3,"type":"subheading","text":"1. Programmatic Builds with BuildPipeline"},{"order":4,"type":"paragraph","text":"Using Unity's ScriptableBuildPipeline allows you to automate your build process, integrate with CI/CD pipelines, and configure custom build steps. Create an Editor script to handle the build execution."},{"order":5,"type":"code","text":"using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

public class AutomatedBuilder
{
    [MenuItem("Build/Build Windows Player")]
    public static void BuildWindows()
    {
        BuildPlayerOptions buildPlayerOptions = new BuildPlayerOptions();
        buildPlayerOptions.scenes = new[] { "Assets/Scenes/Main.unity" };
        buildPlayerOptions.locationPathName = "Builds/Windows/Game.exe";
        buildPlayerOptions.target = BuildTarget.StandaloneWindows64;
        buildPlayerOptions.options = BuildOptions.None;

        BuildReport report = BuildPipeline.BuildPlayer(buildPlayerOptions);
        BuildSummary summary = report.summary;

        if (summary.result == BuildResult.Succeeded)
        {
            Debug.Log("Build succeeded: " + summary.totalSize + " bytes");
        }

        if (summary.result == BuildResult.Failed)
        {
            Debug.Log("Build failed");
        }
    }
}"},{"order":6,"type":"subheading","text":"2. Asset Bundles Implementation"},{"order":7,"type":"paragraph","text":"Asset Bundles allow you to package assets outside of your main build, enabling downloadable content (DLC) and reduced initial application sizes. First, tag your assets by setting their AssetBundle name in the inspector, or programmatically."},{"order":8,"type":"code","text":"using UnityEditor;

public class CreateAssetBundles
{
    [MenuItem("Assets/Build AssetBundles")]
    static void BuildAllAssetBundles()
    {
        string assetBundleDirectory = "Assets/StreamingAssets";
        if (!System.IO.Directory.Exists(assetBundleDirectory))
        {
            System.IO.Directory.CreateDirectory(assetBundleDirectory);
        }

        BuildPipeline.BuildAssetBundles(assetBundleDirectory, 
            BuildAssetBundleOptions.None, 
            BuildTarget.StandaloneWindows64);
    }
}"},{"order":9,"type":"subheading","text":"3. Loading Asset Bundles at Runtime"},{"order":10,"type":"paragraph","text":"Once built, load your bundles asynchronously at runtime to prevent frame rate drops during gameplay. Always remember to unload bundles when they are no longer needed."},{"order":11,"type":"code","text":"using System.Collections;
using UnityEngine;

public class AssetBundleLoader : MonoBehaviour
{
    IEnumerator Start()
    {
        string bundlePath = System.IO.Path.Combine(Application.streamingAssetsPath, "mybundle");
        AssetBundleCreateRequest bundleRequest = AssetBundle.LoadFromFileAsync(bundlePath);
        yield return bundleRequest;

        AssetBundle bundle = bundleRequest.assetBundle;
        if (bundle == null)
        {
            Debug.LogError("Failed to load AssetBundle!");
            yield break;
        }

        AssetRequest assetRequest = bundle.LoadAssetAsync<GameObject>("MyPrefab");
        yield return assetRequest;

        Instantiate(assetRequest.asset);
        bundle.Unload(false);
    }
}"},{"order":12,"type":"subheading","text":"4. Platform-Specific Optimization Best Practices"},{"order":13,"type":"bullet_point","text":"Texture Compression: Use ASTC for modern mobile platforms (Android/iOS), DXT5/BC7 for Desktop, and ETC2 for older Android hardware."},{"order":14,"type":"bullet_point","text":"Audio Settings: Compress audio clips using Vorbis for music and ADPCM or PCM for short sound effects depending on target memory footprints."},{"order":15,"type":"bullet_point","text":"Scripting Backend: Target IL2CPP for ARM64 mobile builds and WebGL to enable stripping and high-performance ahead-of-time compilation."},{"order":16,"type":"bullet_point","text":"Graphics APIs: Prioritize Vulkan on Android and Metal on iOS while maintaining fallback support for OpenGL ES 3.0."},{"order":17,"type":"paragraph","text":"By combining structured automated build pipelines with optimized Asset Bundle strategies, you can scale your Unity projects efficiently across multiple target platforms while keeping build times fast and memory usage low."}]
